        gpa.free(v);
        fb.detail |= 1 << 0;
    } else |e| fb.err = e;

    if (enc.delta_binary_packed.decodeInt32(gpa, data)) |v| {
        gpa.free(v);
        fb.detail |= 1 << 1;
    } else |e| fb.err = e;

