                } else {
                    values[i] = .{ .null_val = {} };
                }
            } else {
                values[i] = .{ .null_val = {} };
            }
        }
    }

    return .{
        .values = values,
        .def_levels = levels_info.def_levels,
        .rep_levels = levels_info.rep_levels,
    };
