        },
        1 => {
            var v = try format.PageHeader.parse(a, &reader);
            v.deinit(a);
        },
        2 => {
            var v = try format.page_index.ColumnIndex.parse(a, &reader);
            v.deinit(a);
        },
        else => {
            var v = try format.page_index.OffsetIndex.parse(a, &reader);
            v.deinit(a);
        },
    }
}
